<style>
body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#222}
a{color:#175b9c}
h2{margin-top:2rem;border-bottom:1px solid #eee;padding-bottom:.3rem}
